// V47 Input Normalizer - single output
// [V47.7] Added New_Order_ID forwarding for Order_ID rename support
const input = $input.all()[0].json;
const rawPayload = (input.body !== undefined) ? input.body : input;
const body = Array.isArray(rawPayload) ? (rawPayload[0] || {}) : rawPayload;
const action = (body.action || body.Action || input.action || input.Action || "create").toLowerCase();
return [{
  json: {
    ...input,
    action: action,
    isDelete: (action === 'delete'),
    Record_ID: body.Record_ID || body.id || input.Record_ID || "",
    Order_ID: body.Order_ID || input.Order_ID || "",
    New_Order_ID: body.New_Order_ID || input.New_Order_ID || null,
    Customer_Name: body.Customer_Name || input.Customer_Name || ""
  }
}];

const calcItem = $('Calculate Profit & Pack Items').all()[0];
const calc = calcItem ? calcItem.json : {};
const trigger = $('Receive Dashboard Order').first().json;
const body = trigger.body || trigger;

const hasCostError = calc.Has_Cost_Error === true || calc.Total_Cost === 0;
const action = body.action || body.Action || 'create';

// 測試訂單（Order_ID 符合 test+數字，如 test1001）不逐單發 Telegram，
// 由 FHS_System_StressTester.py 收集全部案例後另發一則彙總訊息（避免騷擾）。
const orderId = calc.Order_ID || '';
if (/^test\d+$/i.test(orderId)) {
  return [];
}

// When cost unavailable, omit '$' prefix to avoid '$⚠️ 待核算'
const costDisplay   = hasCostError ? '⚠️ 待核算' : '$' + calc.Total_Cost;
const profitDisplay = hasCostError ? '⚠️ 待核算' : '$' + calc.Final_Profit;
const revenueDisplay = '$' + (calc.Total_Revenue || 0);

let message = '';

if (action === 'create') {
  const subItems = calc.Sub_Items || [];
  const orderLines = subItems.length > 0
    ? subItems.map(item => {
        const qty = item.Quantity > 1 ? ' x' + item.Quantity : '';
        return '• ' + (item.Product_Name || '') + qty;
      }).join('\n')
    : '  (無商品記錄)';

  message = [
    '📦 【Freehandsss 新訂單】',
    '👤 ' + (calc.Customer_Name || '') + '  |  📝 #' + (calc.Order_ID || ''),
    '📅 ' + (calc.Appointment_Date || '未定'),
    '------------------------',
    '🛍️ 訂單商品：',
    orderLines,
    '------------------------',
    '💰 入帳：' + revenueDisplay,
    '💵 成本：' + costDisplay,
    '🏆 利潤：' + profitDisplay
  ].join('\n');

} else if (action === 'edit') {
  const updateNote = body.Update_Note ? '\n' + body.Update_Note : '';
  message = [
    '✏️ 【Freehandsss 修正訂單】',
    '👤 ' + (calc.Customer_Name || '') + '  |  📝 #' + (calc.Order_ID || ''),
    '📅 ' + (calc.Appointment_Date || '未定') + updateNote,
    '------------------------',
    '💰 入帳：' + revenueDisplay,
    '💵 成本：' + costDisplay,
    '🏆 利潤：' + profitDisplay
  ].join('\n');

} else {
  message = '🗑️ 【Freehandsss 刪除訂單】\n👤 ' + (calc.Customer_Name || '') + '  |  📝 #' + (calc.Order_ID || '') + '\n⚠️ 此訂單已被刪除';
}

return [{ json: {
  Action:         action,
  Customer_Name:  calc.Customer_Name || '',
  Order_ID:       calc.Order_ID || '',
  Full_Message:   message,
  Has_Cost_Error: hasCostError
}}];

// V47.16 (2026-07-28 cl-flow 2026-07-28-1121) — 新增 family_member_config 欄位傳遞（migration
// 0081），供家庭組合鎖匙扣(V2)動態畫圖審計顯示。其餘邏輯逐字不變。
// 前身 V47.15 (2026-07-25 cl-flow 2026-07-25-0148) — 新增 accessory_cost 欄位傳遞（migration
// 0079/0080），修復配件成本（羊毛氈/燈飾加購）漏落訂單層分類 rollup 嘅顯示缺口。
// 前身 V47.14 (2026-07-24 cl-flow 2026-07-24-0213 Phase2) — 新增 position_code/drawing_waived/
// drawing_charged_count/cost_model_version 四個欄位傳遞（migration 0073/0075），
// 其餘邏輯逐字不變。
const input = $input.first().json;
const action = (() => {
  try { return ($('Input Normalizer').first().json.action || 'create').toLowerCase(); } catch(e) { return 'create'; }
})();
const oldOrderId = input.Order_ID;
const newOrderId = (() => {
  try { return $('Input Normalizer').first().json.New_Order_ID || null; } catch(e) { return null; }
})();

const staticData = $getWorkflowStaticData('global');
const supabaseActive = staticData.supabase_mirror_enabled !== false;

// 2026-08-10 security fix (D62): 原本寫死嘅 fallback secret key 已喺公開 GitHub repo 曝光並被
// Supabase 自動撤銷。移除硬編碼 fallback，改為讀環境變數。
// 兩條讀取路徑都試（n8n 原生 $env 優先；process.env 喺 Code node 沙盒/task runner 下常被封鎖），
// 失敗時拋出帶診斷資訊嘅錯誤，方便由執行記錄一眼判斷係「變數未設」定係「沙盒封鎖」。
const _keyProbe = { via$env: null, viaProcess: null, $envErr: null, procErr: null };
try { _keyProbe.via$env = (typeof $env !== 'undefined' && $env) ? ($env.SUPABASE_SERVICE_KEY || null) : null; }
catch(e) { _keyProbe.$envErr = String(e && e.message || e).slice(0, 120); }
try { _keyProbe.viaProcess = (typeof process !== 'undefined' && process.env) ? (process.env.SUPABASE_SERVICE_KEY || null) : null; }
catch(e) { _keyProbe.procErr = String(e && e.message || e).slice(0, 120); }

const SUPABASE_KEY = _keyProbe.via$env || _keyProbe.viaProcess || null;
if (supabaseActive && !SUPABASE_KEY) {
  throw new Error(
    'SUPABASE_SERVICE_KEY 讀唔到 — 診斷：' +
    '$env=' + (_keyProbe.via$env ? 'HIT' : 'miss') +
    (_keyProbe.$envErr ? '(err:' + _keyProbe.$envErr + ')' : '') +
    ' | process.env=' + (_keyProbe.viaProcess ? 'HIT' : 'miss') +
    (_keyProbe.procErr ? '(err:' + _keyProbe.procErr + ')' : '') +
    ' | typeof $env=' + (typeof $env) + ', typeof process=' + (typeof process)
  );
}

// Build lookup from original webhook items to preserve UI-edited process_status & batch_number
let uiItemMap = {};
try {
  const triggerBody = $('Receive Dashboard Order').first().json.body || $('Receive Dashboard Order').first().json;
  (triggerBody.Order_Items_List || []).forEach(function(it) {
    if (it.Order_Item_Key) {
      uiItemMap[it.Order_Item_Key] = {
        process_status: it._ui_process_status || null,
        batch_number: it._ui_batch_number || null
      };
    }
  });
} catch(e) { /* Receive Dashboard Order not in scope */ }

let rawFormState = {};
try {
  rawFormState = typeof input.Raw_Form_State === 'string'
    ? JSON.parse(input.Raw_Form_State || '{}')
    : (input.Raw_Form_State || {});
} catch(e) { rawFormState = { raw: String(input.Raw_Form_State) }; }

// [item_sale_price] Parse balanceSplitData + depositSplitData → _splitMap
// splitData format: {"TEMP_P_MAIN##": 1680, "TEMP_K_rf#🦶 右腳#嬰兒": 2000}
// Key suffix rule: "TEMP_P_MAIN##" → "P_MAIN", "TEMP_K_rf#..." → "K_RF"
const _splitMap = {};
['balanceSplitData', 'depositSplitData'].forEach(function(dataKey) {
  let splitData = rawFormState[dataKey];
  if (typeof splitData === 'string') {
    try { splitData = JSON.parse(splitData); } catch(e) { splitData = {}; }
  }
  if (splitData && typeof splitData === 'object' && !Array.isArray(splitData)) {
    Object.keys(splitData).forEach(function(key) {
      const suffix = key.replace('TEMP_', '').split('#')[0].toUpperCase();
      _splitMap[suffix] = (_splitMap[suffix] || 0) + (Number(splitData[key]) || 0);
    });
  }
});

// [B7 fix] final_sale_price = Deposit + Balance + Additional_Fee（確收守護）
// Total_Revenue 是系統建議售價，不可作為確收依據，禁止覆蓋操作者確認金額
const _confirmedRevenue = (input.Deposit || 0) + (input.Balance || 0) + (input.Additional_Fee || 0);

// Sum validation: splitMap total must equal final_sale_price ±$1 (epsilon for rounding)
const _splitTotal = Object.values(_splitMap).reduce(function(s, v) { return s + v; }, 0);
const _hasSplitData = Object.keys(_splitMap).length > 0;
const _splitValid = !_hasSplitData || Math.abs(_splitTotal - _confirmedRevenue) <= 1;
// If validation fails: item_sale_price = null → RPC 3-layer fallback takes over

const order = {
  customer_name: input.Customer_Name || oldOrderId,
  appointment_at: input.Appointment_Date || null,
  final_sale_price: _confirmedRevenue,
  total_cost: input.Total_Cost || 0,
  net_profit: _confirmedRevenue - (input.Total_Cost || 0),
  deposit: input.Deposit || 0,
  balance: input.Balance || 0,
  additional_fee: input.Additional_Fee || 0,
  full_order_text: input.Order_Text || '',
  handmodel_cost: input.Handmodel_Cost_Total || 0,
  keychain_cost: input.Keychain_Cost_Total || 0,
  necklace_cost: input.Necklace_Cost_Total || 0,
  accessory_cost: input.Accessory_Cost_Total || 0,
  n8n_cost_adjustments: Number(input.N8n_Cost_Adjustments) || 0,
  n8n_adjustment_notes: input.N8n_Adjustment_Notes || [],
  raw_form_state: rawFormState
};

if (action === 'create') {
  order.process_status = '待確認';
  if (input.Order_Confirm_Date) {
    order.confirmed_at = input.Order_Confirm_Date;
  }
}

const items = (input.Sub_Items || []).map((item, index) => {
  const ui = uiItemMap[item.Order_Item_Key] || {};
  // [Session 84 B-fix] 鎖匙扣/吊飾的刻字存放在 item.Notes（[上排]X [下排]Y / 單字），
  // 需導入 engraving_text 欄位；手模(立體擺設)刻字走 raw_form_state.pEngraving（由前端 mapOrder fallback 處理），不在此。
  const _isEngCat = (item.Item_Category === '金屬鎖匙扣' || item.Item_Category === '純銀頸鏈吊飾');

  // [item_sale_price] Map item_key suffix → _splitMap entry
  const _itemKeySuffix = (item.Order_Item_Key || '').replace(oldOrderId + '_', '').toUpperCase();
  const _itemSalePrice = (_splitValid && _hasSplitData && _splitMap[_itemKeySuffix] != null)
    ? _splitMap[_itemKeySuffix]
    : null;

  return {
    item_key: item.Order_Item_Key || (oldOrderId + '_' + index + '_AUTO'),
    product_sku: item.Product_Name || null,
    item_category: item.Item_Category || null,
    quantity: item.Quantity || 1,
    item_base_cost: item.Total_Base_Cost || 0,
    subtotal_cost: item.Total_Base_Cost || 0,
    handmodel_cost: item.Handmodel_Cost || 0,
    keychain_cost: item.Keychain_Cost || 0,
    necklace_cost: item.Necklace_Cost || 0,
    accessory_cost: item.Accessory_Cost || 0,
    specification: item.Notes || '',
    engraving_text: _isEngCat ? (item.Notes || '') : '',
    process_status: ui.process_status || null,
    batch_number: ui.batch_number || null,
    // Task A: 四分量成本欄位（0027 已建欄，此處填值）
    drawing_cost:  Number(item.Drawing_Cost)  || 0,
    printing_cost: Number(item.Printing_Cost) || 0,
    chain_cost:    Number(item.Chain_Cost)    || 0,
    shipping_cost: Number(item.Shipping_Cost) || 0,
    // [item_sale_price] 精確品項售價（V42+ splitData 有值則填，否則 null → RPC fallback）
    item_sale_price: _itemSalePrice,
    // cl-flow 2026-07-24-0213 Phase2（migration 0073/0075）：結構化畫圖扣減審計欄位，V2 SKU專屬
    position_code: item.Position_Code || null,
    drawing_waived: (item.Drawing_Waived === null || item.Drawing_Waived === undefined) ? null : item.Drawing_Waived,
    drawing_charged_count: (item.Drawing_Charged_Count === null || item.Drawing_Charged_Count === undefined) ? null : item.Drawing_Charged_Count,
    cost_model_version: item.Cost_Model_Version || null,
    // cl-flow 2026-07-28-1121（migration 0081）：家庭組合鎖匙扣(V2)成員結構，供動態畫圖審計顯示
    family_member_config: item.Family_Member_Config || null
  };
});

return [{
  json: {
    supabaseActive,
    supabaseKey: SUPABASE_KEY,
    rpcPayload: {
      p_action: action,
      p_old_order_id: oldOrderId,
      p_new_order_id: newOrderId,
      p_order: order,
      p_items: items
    }
  }
}];
